import{bV as e,aL as t,u as l,G as a}from"./chunks/framework.DvBUyM1S.js";const g=JSON.parse('{"title":"GitHub+jsDelivr+PicGo打造免费图床","description":"","frontmatter":{"title":"GitHub+jsDelivr+PicGo打造免费图床","date":"2021-7-28","tags":[null],"permalink":"/pages/4cf2e1/","categories":["GitHub"]},"headers":[],"relativePath":"06.工具/05.GitHub/03.GitHub+jsDelivr+PicGo打造免费图床.md","filePath":"06.工具/05.GitHub/03.GitHub+jsDelivr+PicGo打造免费图床.md","lastUpdated":1652179217000}'),r={name:"06.工具/05.GitHub/03.GitHub+jsDelivr+PicGo打造免费图床.md"};function o(c,i,s,p,n,d){return t(),l("div",null,[...i[0]||(i[0]=[a('<h1 id="github-jsdelivr-picgo打造免费图床" tabindex="-1">GitHub+jsDelivr+PicGo打造免费图床 <a class="header-anchor" href="#github-jsdelivr-picgo打造免费图床" aria-label="Permalink to &quot;GitHub+jsDelivr+PicGo打造免费图床&quot;">​</a></h1><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230327.jpg" alt="git" loading="lazy"></p><h1 id="github-jsdelivr-picgo打造免费图床-1" tabindex="-1">GitHub+jsDelivr+PicGo打造免费图床 <a class="header-anchor" href="#github-jsdelivr-picgo打造免费图床-1" aria-label="Permalink to &quot;GitHub+jsDelivr+PicGo打造免费图床&quot;">​</a></h1><h2 id="目前图床优劣" tabindex="-1">目前图床优劣 <a class="header-anchor" href="#目前图床优劣" aria-label="Permalink to &quot;目前图床优劣&quot;">​</a></h2><ol><li>微博等博客图床：以前用的人比较多，从 2019 年 4 月开始开启了防盗链，凉凉。</li><li>SM.MS：运营四年多了，也变得越来越慢了，到了晚上直接打不开图片，速度堪忧。</li><li>其他小众图床：随时有挂掉的风险。</li><li>Imgur等国外图床：国内访问速度太慢，随时有被墙的风险。</li><li>优质储存服务：例如七牛云、又拍云、腾讯云COS、阿里云OSS等，操作繁琐，又是实名认证又是域名备案的等。说真的以后网站的访问量大的话，还的买带宽等服务，按月收费，费用高。</li><li>GitHub 图床：免费，但是国内访问速度慢（利用 jsDelivr 提供的免费的 CDN 加速，鸡贼）</li></ol><h2 id="搭建教程" tabindex="-1">搭建教程 <a class="header-anchor" href="#搭建教程" aria-label="Permalink to &quot;搭建教程&quot;">​</a></h2><ol><li>新建 GitHub 仓库</li><li>创建个人访问令牌</li><li>配置 PicGo 设置</li><li>上传图片，获取jsDelivr 地址</li></ol><h3 id="新建-github-仓库" tabindex="-1">新建 GitHub 仓库 <a class="header-anchor" href="#新建-github-仓库" aria-label="Permalink to &quot;新建 GitHub 仓库&quot;">​</a></h3><p>创建一个仓库，用来存放图片。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230340.jpg" alt="-w1059" loading="lazy"></p><h3 id="生成个人访问令牌token" tabindex="-1">生成个人访问令牌Token <a class="header-anchor" href="#生成个人访问令牌token" aria-label="Permalink to &quot;生成个人访问令牌Token&quot;">​</a></h3><p><a href="https://github.com/settings/tokens" target="_blank" rel="noreferrer">前往设置</a></p><p>作用：授权仓库的操作权限，通过API实现自动化。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230334.jpg" alt="-w1139" loading="lazy"></p><p>然后填写 <code>Token</code> 描述，勾选 repo、write、read然后点击 <code>Generate token</code> 生成一个 <code>Token</code></p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200714002302.jpg" alt="token" loading="lazy"></p><p>因为 Token 只会显示一次，所以先保存笔记本等。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230337.jpg" alt="-w1030" loading="lazy"></p><h3 id="配置-picgo" tabindex="-1">配置 PicGo <a class="header-anchor" href="#配置-picgo" aria-label="Permalink to &quot;配置 PicGo&quot;">​</a></h3><p><a href="https://github.com/Molunerfinn/picgo/releases" target="_blank" rel="noreferrer">前往PicGo官网</a></p><p>安装好后开始配置图床</p><ol><li><p>设定仓库名：按照 用户名/仓库名 的格式填写（就是刚才创建的仓库）</p></li><li><p>设定分支名：master</p></li><li><p>设定 Token：粘贴之前叫你保存的Token。</p></li><li><p>设定自定义域名：它的的作用是，在图片上传后，PicGo 会按照自定义域名+上传的图片名的方式生成访问链接，放到粘贴板上。 <code>https://cdn.jsdelivr.net/gh/用户名/仓库名</code></p></li></ol><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230329.jpg" alt="-w800" loading="lazy"></p><h3 id="上传图片测试" tabindex="-1">上传图片测试 <a class="header-anchor" href="#上传图片测试" aria-label="Permalink to &quot;上传图片测试&quot;">​</a></h3><p>上传图片后，在相册可以看到刚才的图片，点击复制的URL就是通过<code>jsdelivr</code> CDN加速的。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230348.jpg" alt="-w800" loading="lazy"></p><p>此外 PicGo 还有相册功能，可以对已上传的图片进行删除，修改链接等快捷操作，PicGo 还可以生成不同格式的链接、支持批量上传、快捷键上传、自定义链接格式、上传前重命名等，更多功能自己去探索吧！</p><p>最后，以上步骤只是通过工具提升效率罢了，了解github地址转化成jsDelivr地址规则，其实就能愉快的撸羊毛。</p><blockquote><p>某分支和版本号大小不能超过50M会直接被jsDelivr屏蔽。所以单某个分支接近临界值，换分支继续就得了。</p></blockquote><p>相关文章</p><p><a href="https://qqlcx5.github.io/other/github/" target="_blank" rel="noreferrer">GitHub 通过 jsdelivr CDN加持</a></p><p>参考文章</p><ul><li><a href="https://www.cnblogs.com/sitoi/p/11848816.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/sitoi/p/11848816.html</a></li></ul>',33)])])}const u=e(r,[["render",o]]);export{g as __pageData,u as default};
